import{_ as t,c as e,o as a,a4 as r}from"./chunks/framework.BYxathSa.js";const h=JSON.parse('{"title":"Q1：React 的核心理念与特点","description":"","frontmatter":{},"headers":[],"relativePath":"react/q1.md","filePath":"react/q1.md","lastUpdated":null}'),o={name:"react/q1.md"},s=r('<h1 id="q1-react-的核心理念与特点" tabindex="-1">Q1：React 的核心理念与特点 <a class="header-anchor" href="#q1-react-的核心理念与特点" aria-label="Permalink to &quot;Q1：React 的核心理念与特点&quot;">​</a></h1><ul><li><strong>声明式</strong>：React 让你只需描述 UI 应该是什么样子，当数据变化时，它会高效地更新和重新渲染恰当的组件。</li><li><strong>组件化</strong>：UI 被拆分成独立、可复用的组件，每个组件封装了自己的结构和逻辑。</li><li><strong>虚拟 DOM</strong>：在内存中维护一棵轻量级的虚拟 DOM 树，状态变化时生成新的虚拟树，通过 Diff 算法计算出最小变更，再批量更新真实 DOM，极大提升性能。</li><li><strong>单向数据流</strong>：数据从父组件通过 props 流向子组件，数据流动清晰，容易追踪和调试。</li><li><strong>一次学习，随处编写</strong>：可开发 Web、移动端（React Native）、桌面端等。</li></ul>',2),n=[s];function c(i,l,_,d,p,f){return a(),e("div",null,n)}const m=t(o,[["render",c]]);export{h as __pageData,m as default};
